def build_nature_wildlife(existing_norms: set[str]):
    entries = []
    seen = set()
    rank = 1

    for row in NATURE_ITEMS:
        headword = row[0]
        norm = norm_vocab(headword)
        if norm in existing_norms or norm in seen:
            continue
        seen.add(norm)

        gender = row[1]
        level = row[2]
        msa = row[3]
        eg = row[4]
        domain = row[5]

        art = "El" if gender == "m" else "La"
        ex_es = f"{art} {headword} es una maravilla de la naturaleza y del medio ambiente."
        ex_ar = f"الـ{msa} من روائع الطبيعة والبيئة الحية."

        entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        entries.append(entry)
        rank += 1

    emit_bundle(
        filename="vocab-cv-nature-wildlife.json",
        bundle_slug="cv-nature-wildlife",
        title_ar="معجم الطبيعة والكائنات الحية والحيوانات والنباتات والتضاريس",
        entries=entries
    )
    return len(entries), seen

if __name__ == "__main__":
    count, _ = build_nature_wildlife(get_existing_norms())
    print(f"Generated {count} entries in vocab-cv-nature-wildlife.json")
